B.aRH={decor_boulder_a:0,decor_node_tree_capwood:1,decor_node_tree_capwood_cut:2,decor_node_tree_charwood:3,decor_node_tree_charwood_cut:4,decor_node_tree_ironbark:5,decor_node_tree_ironbark_cut:6,decor_node_tree_oak:7,decor_node_tree_oak_cut:8,decor_node_tree_pine:9,decor_node_tree_pine_cut:10,decor_node_tree_palmwood_cut:11,decor_node_tree_willow:12,decor_node_tree_willow_cut:13,decor_node_ore_coal:14,decor_node_ore_copper:15,decor_node_ore_iron:16,decor_node_ore_mithril:17,decor_node_ore_silver:18,decor_node_ore_tin:19,decor_node_ore_brimstone:20,decor_node_ore_cobalt:21,decor_node_herb_saltwort:22,decor_node_herb_bitterroot:23,decor_node_herb_bitterroot_cave:24,decor_node_herb_bloodthistle:25,decor_node_herb_bloodthistle_cave:26,decor_node_herb_duskbloom:27,decor_node_herb_duskbloom_cave:28,decor_node_herb_emberleaf:29,decor_node_herb_emberleaf_cave:30,decor_node_herb_mossbell:31,decor_node_herb_mossbell_cave:32,decor_node_herb_sunleaf:33,decor_node_herb_sunleaf_cave:34,homestead_plot_herb_1:35,homestead_plot_herb_2:36,homestead_plot_herb_3:37,homestead_plot_ore_1:38,homestead_plot_ore_2:39,homestead_plot_ore_3:40,homestead_plot_tree_1:41,homestead_plot_tree_2:42,homestead_plot_tree_3:43,quest_prop_bones:44,quest_prop_bundle:45,quest_prop_debris:46,quest_prop_lamp:47,quest_prop_post:48,quest_prop_sack:49,quest_prop_sword:50,quest_prop_tracks:51,exit_portal_0:52,exit_portal_1:53,exit_portal_2:54,exit_portal_3:55,exit_portal_4:56,exit_portal_5:57,homestead_tent_pitched:58,decor_workbench:59,decor_boulder_b:60,decor_hollow_stall:61,decor_hollow_cistern:62,decor_hollow_lamp:63,decor_hollow_board:64}
